(()=>{document.addEventListener("DOMContentLoaded",()=>{let s=document.querySelectorAll("[data-ws-wishlist]");if(!s.length||typeof WooShopWishlist=="undefined")return;let d=async e=>{let i=e.dataset.productId;if(!i)return;e.disabled=!0;let t=new FormData;t.append("action",WooShopWishlist.action),t.append("nonce",WooShopWishlist.nonce),t.append("product_id",i);try{let r=await(await fetch(WooShopWishlist.ajaxUrl,{method:"POST",body:t})).json();if(!r.success)return;let o=r.data.active;e.classList.toggle("is-active",o),e.setAttribute("aria-pressed",o?"true":"false"),e.setAttribute("aria-label",o?WooShopWishlist.removeText:WooShopWishlist.addText);let n=e.querySelector(".ws-wishlist-button__text");n&&(n.textContent=o?WooShopWishlist.removeText:WooShopWishlist.addText)}catch(a){console.error("WooShop wishlist error:",a)}finally{e.disabled=!1}};s.forEach(e=>{e.addEventListener("click",()=>d(e))})});})();
